static inline
void
__qobd_str_append_u32_trim(
    _QOBD_StringPrintContext * ctx,
    qo_uint32_t                 value
) {
    if (!ctx || !ctx->current_pos || ctx->remaining_size <= 0)
        return;

    qo_uint32_t digits = QO_DEC_DIGITS32(value);
    
    if (digits > ctx->remaining_size)
    {
        char holder[11];
        qo_10udec_to_str_trimmed(value, holder);
        memcpy(ctx->current_pos, holder, ctx->remaining_size);
        __qobd_str_append_update_pos(ctx, ctx->remaining_size);
        *ctx->current_pos = '\0';
    }
    else {
        qo_10udec_to_str_trimmed(value, ctx->current_pos);
        __qobd_str_append_update_pos(ctx, digits);
    }
}

static inline
void
__qobd_str_append_i32_trim(
    _QOBD_StringPrintContext * ctx,
    qo_int32_t                  value
) {
    if (!ctx || !ctx->current_pos || ctx->remaining_size <= 0)
        return;

    // 处理符号
    qo_bool_t is_negative = value & 0x80000000;
    if ((ctx->format.int_fmt_mode.switches.always_show_sign && !is_negative) || is_negative) {
        if (ctx->remaining_size <= 1) {
            // 只有一个字符位置，只能放终止符
            *ctx->current_pos = '\0';
            ctx->remaining_size = 0;
            return;
        }
        
        *ctx->current_pos = is_negative ? '-' : '+';
        ctx->current_pos++;
        ctx->remaining_size--;
    }
    
    // 转换为无符号值处理
    qo_uint32_t positive_value;
    if (value == QO_INT32_MIN) {
        positive_value = 2147483648u;  // 2^31
    } else {
        positive_value = is_negative ? (qo_uint32_t)(-value) : (qo_uint32_t)value;
    }
    
    // 复用无符号数转换函数
    __qobd_str_append_u32_trim(ctx, positive_value);
}

static inline
void
__qobd_str_append_u16(
    _QOBD_StringPrintContext * ctx,
    qo_uint16_t                  value
) {
    if (!ctx ||!ctx->current_pos || ctx->remaining_size <= 0)
        return;

    qo_uint32_t digits = QO_DEC_DIGITS32(value);
    if (digits > ctx->remaining_size)
    {
        char holder[6];
        qo_4udec_to_str(value, holder);
        memcpy(ctx->current_pos, holder, ctx->remaining_size);
        __qobd_str_append_update_pos(ctx , ctx->remaining_size);
        *ctx->current_pos = '\0';
    }
    else {
        qo_4udec_to_str(value, ctx->current_pos);
        __qobd_str_append_update_pos(ctx, 5);
    }
}

static inline
void
__qobd_str_append_i16(
    _QOBD_StringPrintContext * ctx ,
    qo_int16_t                   value
) {
    if (!ctx ||!ctx->current_pos || ctx->remaining_size <= 0)
        return;

    qo_bool_t is_negative = value & (qo_int16_t)0x8000;
    if ((ctx->format.int_fmt_mode.switches.always_show_sign &&!is_negative) || is_negative) {
        if (ctx->remaining_size <= 1) {
            // 只有一个字符位置，只能放终止符
            *ctx->current_pos = '\0';
            ctx->remaining_size = 0;
            return;
        }
        *ctx->current_pos = is_negative? '-' : '+';
        ctx->current_pos++;
        ctx->remaining_size--;
    }

    qo_uint32_t positive_value;
    if (value == -32768) {
        positive_value = 32768u;  // 2^15
    } else {
        positive_value = is_negative? (qo_uint32_t)(-value) : (qo_uint32_t)value;
    }

    __qobd_str_append_u16(ctx, positive_value);
}
