#define qobd_strprint(target , buf_size , p_result , ...) \
    do { \
        QOBD_StringPrintResult res; \
        if (!target) \
        { \
            break; \
        } \
        _QOBD_StringPrintContext  ctx; \
        ctx.format = QOBD_STRING_PRINT_FORMAT_DEFAULT; \
        ctx.current_pos = target; \
        ctx.remaining_size = buf_size; \
        if (ctx.remaining_size > 0) \
        { \
            *ctx.current_pos = '\0'; \
            __QOBD_FOR_EACH(&ctx , __QOBD_STR_APPEND_CTX_DISPATCH , ##__VA_ARGS__); \
            if (ctx.remaining_size == 0) \
            { \
                ((qo_cstring_t) (target))[(buf_size) - 1] = '\0'; \
                res.truncated = 1; \
            } \
            else \
            { \
                res.truncated = 0; \
            } \
            res.size = (buf_size); \
        } \
        \
        if (p_result) \
        { \
            *p_result = res; \
        } \
    } while (0)


